source_quote:
Avoid referencing `block_mean` on the dead branch of the inline `if-else` when `IS_RMS_NORM` is True, as it is undefined and can cause compilation errors. Use static `if-else` blocks instead.
> ```suggestion
if not IS_RMS_NORM:
block_x_hat = (block_x - block_mean[:, None]) * block_rstd[:, None]
else:
block_x_hat = block_x * block_rstd[:, None]

pattern.code:
@triton.jit
def layer_norm_gated_fwd_kernel(
    X_ptr, Y_ptr, W_ptr, B_ptr,
    mean_ptr, rstd_ptr,
    N, eps,
    IS_RMS_NORM: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    x_ptr = X_ptr + pid * N
    y_ptr = Y_ptr + pid * N
    cols = tl.arange(0, BLOCK_SIZE)
    mask = cols < N

    x = tl.load(x_ptr + cols, mask=mask, other=0.0).to(tl.float32)

    if not IS_RMS_NORM:
        b_mean = tl.load(mean_ptr + pid)
        b_rstd = tl.load(rstd_ptr + pid)
    else:
        b_rstd = tl.load(rstd_ptr + pid)

    # static if-else — 只有对应分支会被执行，避免 dead branch 引用未定义变量
    if IS_RMS_NORM:
        b_x_hat = b_x * b_rstd[:, None]
    else:
        b_x_hat = (b_x - b_mean[:, None]) * b_rstd[:, None]
    b_y = b_x_hat * tl.load(W_ptr + cols, mask=mask, other=0.0) + tl.load(B_ptr + cols, mask=mask, other=0.0)
    tl.store(y_ptr + cols, b_y.to(Y_ptr.dtype.element_ty), mask=mask)


